steps.script:
window.__arTabs = {
  page: () => document.querySelector('#AccessRolesConfigPage:not(.hide)'),
  panels: () => [...document.querySelectorAll('.jfar-backdrop .jfar-panel')],
  top: () => __arTabs.panels().pop() || null,
  title: () => { const t = __arTabs.top(); return t ? t.querySelector('.jfar-panel-header h3').textContent : null; },
  button: (root, text) => [...(root || document).querySelectorAll('button')].find(b => b.textContent === text) || null,
  press: (root, text) => { const b = __arTabs.button(root, text); if (!b) throw new Error('no button ' + text); if (b.disabled) throw new Error(text + ' is disabled'); b.click(); return true; },
  shown: (el) => !!el && el.getClientRects().length > 0 && !el.closest('[hidden]'),
  chip: (id) => __arTabs.page().querySelector('#AccessRolesChips [data-chip="' + id + '"]'),
  card: (name) => [...__arTabs.page().querySelectorAll('.jfar-page-library')].find(c => c.querySelector('.jfar-page-library-name').textContent === name) || null,
  setting: (name) => __arTabs.page().querySelector('[data-setting="' + name + '"]'),
  set: (el, value) => { el.value = String(value); el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); return el.value; },
  id: (x) => String(x || '').replace(/-/g, '').toLowerCase(),
  seen: [],
  toasts: () => __arTabs.seen.concat([...document.querySelectorAll('.jfar-toast')].map(t => t.textContent))
};
// Every toast's text as it comes (a toast goes after 4 s, maybe before a wait sees it).
new MutationObserver(() => { document.querySelectorAll('.jfar-toast').forEach(t => { if (!__arTabs.seen.includes(t.textContent)) __arTabs.seen.push(t.textContent); }); }).observe(document.body, { childList: true, subtree: true });
return true;
